def compute_basins(self):
    basins = {}
    for x in range(self.n):
        orb = self.orbit(x)
        fp = orb[-1]
        if fp not in basins:
            basins[fp] = set()
        basins[fp].add(x)
    return basins

def tropical_gradient_flow(W):
    n = W.shape[0]
    raw_depth = np.array([-np.max(W[:, i]) for i in range(n)])
    depth = raw_depth - np.min(raw_depth)
    def step(i):
        best_j, best_d = i, depth[i]
        for j in range(n):
            if W[i,j] > 0 and depth[j] < best_d:
                best_j, best_d = j, depth[j]
        return best_j
    return LyapunovDDS(n, step, lambda i: float(depth[i]))

def compute_max_cycle_mean(W):
    n = W.shape[0]
    d = np.full((n+1, n), -np.inf)
    for i in range(n): d[0][i] = 0.0
    for k in range(1, n+1):
        for i in range(n):
            for j in range(n):
                if d[k-1][j] > -np.inf:
                    d[k][i] = max(d[k][i], d[k-1][j] + W[j,i])
    lam = -np.inf
    for i in range(n):
        if d[n][i] > -np.inf:
            min_r = np.inf
            for k in range(n):
                if d[k][i] > -np.inf:
                    min_r = min(min_r, (d[n][i]-d[k][i])/(n-k))
            lam = max(lam, min_r)
    return lam
